-- Stock issues found in the Nov 2026 count import. Closes all earlier open import issues first.
SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRAN;
UPDATE StockIssues SET Status = 'Dismissed', Resolution = 'Superseded by the 2 Nov 2026 full stock count - all balances replaced.',
       ResolvedBy = 'Stock count import', ResolvedAt = SYSUTCDATETIME()
WHERE Status IN ('Open','InProgress') AND CreatedAt < '2026-11-02';

COMMIT;
SELECT Status, COUNT(*) n FROM StockIssues GROUP BY Status; SELECT IssueType, COUNT(*) n FROM StockIssues WHERE Status='Open' GROUP BY IssueType ORDER BY n DESC;